package com.digitalhealth.service;
import com.digitalhealth.dto.HealthcareCenterDTO; import com.digitalhealth.model.HealthcareCenter; import com.digitalhealth.repository.HealthcareCenterRepository; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class HealthcareCenterService {private final HealthcareCenterRepository repo;public HealthcareCenterService(HealthcareCenterRepository r){repo=r;} public List<HealthcareCenterDTO> list(String q){return (q==null||q.isBlank()?repo.findAll():repo.findByNameContainingIgnoreCaseOrAddressContainingIgnoreCase(q,q)).stream().map(this::dto).toList();} public HealthcareCenterDTO save(Long id,HealthcareCenterDTO d){HealthcareCenter c=id==null?new HealthcareCenter():repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Healthcare center not found"));c.setName(d.name);c.setAddress(d.address);c.setDistrict(d.district);c.setContactNumber(d.contactNumber);c.setServices(d.services);c.setOperatingHours(d.operatingHours);c.setStatus(d.status);return dto(repo.save(c));} public void delete(Long id){repo.delete(repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Healthcare center not found")));} private HealthcareCenterDTO dto(HealthcareCenter c){var d=new HealthcareCenterDTO();d.id=c.getId();d.name=c.getName();d.address=c.getAddress();d.district=c.getDistrict();d.contactNumber=c.getContactNumber();d.services=c.getServices();d.operatingHours=c.getOperatingHours();d.status=c.getStatus();return d;}}
